def walk(x,path=''):
    if isinstance(x, dict):
        if x.get('type') in ('select','conditional') or x.get('name') in ('metric','operation_selector','tool_selector','input_mode','suffix_filter','inputs'):
            print('\\nPATH', path, 'name=', x.get('name'), 'type=', x.get('type'), 'label=', x.get('label'), 'value=', x.get('value'))
            if 'options' in x:
                for o in x['options']:
                    print('  OPT', o)
        for k,v in x.items():
            if k not in ('options',): walk(v,path+'/'+str(k))
    elif isinstance(x,list):
        for i,v in enumerate(x): walk(v,path+'/'+str(i))
walk(j.get('inputs',[]))
